(6802224, 1022473, 43774, '<td valign="top">Very cool!!</td>', 'Very cool!!', '2012-06-26 09:45:00.000000', NULL, 1),
(6802248, 1022481, 10785, '<td valign="top">I am totally not seeing a zig zag, since these are all straight lines. But it''s your title! I like the saturated greens and the radial lines are nicely played for your abstract!</td>', 'I am totally not seeing a zig zag, since these are all straight lines. But it''s your title! I like the saturated greens and the radial lines are nicely played for your abstract!', '2012-06-26 11:14:06.000000', NULL, 1),
(6802249, 1021797, 10785, '<td valign="top">You have a lot of great shapes here, but I just can''t seem to focus on anything in this image. There is no focal point. It''s OK that the shot is all blurry, but there needs to be something to focus on, such as a pop of color or a streak of motion or something in the composition to create a focal point.</td>', 'You have a lot of great shapes here, but I just can''t seem to focus on anything in this image. There is no focal point. It''s OK that the shot is all blurry, but there needs to be something to focus on, such as a pop of color or a streak of motion or something in the composition to create a focal point.', '2012-06-26 11:16:40.000000', NULL, 1),
(6802250, 1022647, 10785, '<td valign="top">You got great color and a wonderful composition with the placement of the flower in the frame. It seems to be quite a bit oversharpened and the central focus of the image is lacking in detail.</td>', 'You got great color and a wonderful composition with the placement of the flower in the frame. It seems to be quite a bit oversharpened and the central focus of the image is lacking in detail.', '2012-06-26 11:18:25.000000', NULL, 1),
